"""Embedded runner assets."""
CLEAN_TARGET = '#!/usr/bin/env python3\n"""Remove only the completed OxiDex job\'s default Cargo build directory."""\n\nimport os\nimport shutil\nimport stat\nimport sys\nfrom pathlib import Path\n\n\ndef cleanup(work_root: Path, env: dict[str, str]) -> bool:\n    if env.get("OXIDEX_CLEAN_TARGET") != "1":\n        print("OxiDex target cleanup disabled")\n        return False\n    if env.get("GITHUB_REPOSITORY") != "swack-tools/oxidex":\n        print("OxiDex target cleanup skipped: other repository")\n        return False\n    expected = work_root / "oxidex" / "oxidex"\n    if env.get("GITHUB_WORKSPACE") != str(expected):\n        print("OxiDex target cleanup skipped: unexpected workspace")\n        return False\n    if not shutil.rmtree.avoids_symlink_attacks:\n        raise RuntimeError("safe directory removal is unavailable")\n\n    flags = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW\n    root_fd = os.open(work_root, flags)\n    try:\n        repo_fd = os.open("oxidex", flags, dir_fd=root_fd)\n        try:\n            workspace_fd = os.open("oxidex", flags, dir_fd=repo_fd)\n            try:\n                before = shutil.disk_usage(work_root).free\n                try:\n                    target = os.stat("target", dir_fd=workspace_fd, follow_symlinks=False)\n                except FileNotFoundError:\n                    print(f"OxiDex target absent; free bytes={before}")\n                    return False\n                if not stat.S_ISDIR(target.st_mode):\n                    raise RuntimeError("target is not a directory")\n                # rmtree uses dirfd-relative, fd-based traversal and never follows links.\n                shutil.rmtree("target", dir_fd=workspace_fd)\n                after = shutil.disk_usage(work_root).free\n                print(f"Removed {expected}/target; free bytes before={before} after={after}")\n                return True\n            finally:\n                os.close(workspace_fd)\n        finally:\n            os.close(repo_fd)\n    finally:\n        os.close(root_fd)\n\n\nif __name__ == "__main__":\n    try:\n        cleanup(Path("/work"), os.environ)\n    except (OSError, RuntimeError) as exc:\n        print(f"OxiDex target cleanup failed: {exc}", file=sys.stderr)\n        sys.exit(1)\n'
DOCKER_WRAPPER = '#!/usr/bin/env python3\n"""Per-runner Docker CLI wrapper for GitHub Actions service-container reachability."""\n\nfrom __future__ import annotations\n\nimport fcntl\nimport json\nimport os\nimport re\nimport signal\nimport socket\nimport subprocess\nimport sys\nimport tempfile\nimport time\nfrom pathlib import Path\nfrom typing import Any\n\nREAL_DOCKER = os.environ.get("GHA_REAL_DOCKER", "/usr/bin/docker")\nSTATE_DIR = Path(os.environ.get("GHA_DOCKER_WRAPPER_STATE_DIR", "/tmp/gha-docker-wrapper"))\nHANDSHAKE_TIMEOUT_SEC = float(os.environ.get("GHA_DOCKER_WRAPPER_HANDSHAKE_TIMEOUT", "15.0"))\nNETWORK_NAME_RE = re.compile(r"^github_network_[0-9a-fA-F]+$")\nGLOBAL_VALUE_FLAGS = frozenset({"-H", "--host", "--config", "-c", "--context", "-l", "--log-level"})\n\n\ndef find_subcommand(args: list[str]) -> tuple[str | None, int | None]:\n    i = 0\n    while i < len(args):\n        token = args[i]\n        if token in GLOBAL_VALUE_FLAGS:\n            i += 2\n            continue\n        if any(token.startswith(f"{flag}=") for flag in GLOBAL_VALUE_FLAGS):\n            i += 1\n            continue\n        if token.startswith("-"):\n            i += 1\n            continue\n        return token, i\n    return None, None\n\n\ndef split_global_and_sub_args(args: list[str]) -> tuple[list[str], str | None, list[str]]:\n    subcmd, idx = find_subcommand(args)\n    if subcmd is None or idx is None:\n        return list(args), None, []\n    return list(args[:idx]), subcmd, list(args[idx + 1 :])\n\n\ndef parse_publish_spec(spec: str) -> tuple[str | None, int, int, str] | None:\n    """Parse fixed TCP port publish specs like 3306:3306 or 127.0.0.1:3306:3306."""\n    proto = "tcp"\n    body = spec\n    if "/" in body:\n        body, proto = body.rsplit("/", 1)\n        proto = proto.lower()\n    if proto != "tcp":\n        return None\n    parts = body.split(":")\n    if len(parts) == 2:\n        host_ip = None\n        host_port_str, container_port_str = parts\n    elif len(parts) == 3:\n        host_ip, host_port_str, container_port_str = parts\n    else:\n        return None\n    if not host_port_str.isdigit() or not container_port_str.isdigit():\n        return None\n    host_port = int(host_port_str)\n    container_port = int(container_port_str)\n    if not (1 <= host_port <= 65535 and 1 <= container_port <= 65535):\n        return None\n    return host_ip, host_port, container_port, proto\n\n\ndef extract_option_value(sub_args: list[str], flags: tuple[str, ...]) -> str | None:\n    i = 0\n    while i < len(sub_args):\n        tok = sub_args[i]\n        if tok in flags and i + 1 < len(sub_args):\n            return sub_args[i + 1]\n        for flag in flags:\n            if tok.startswith(f"{flag}="):\n                return tok.split("=", 1)[1]\n        i += 1\n    return None\n\n\ndef rewrite_publish_args(args: list[str]) -> tuple[list[str], dict[int, int]]:\n    """Rewrite fixed TCP -p HPORT:CPORT on github_network_* containers to 127.0.0.1::CPORT."""\n    subcmd, sub_idx = find_subcommand(args)\n    if subcmd not in ("create", "run") or sub_idx is None:\n        return list(args), {}\n\n    network_name = extract_option_value(args[sub_idx + 1 :], ("--network", "--net"))\n    if not network_name or not NETWORK_NAME_RE.match(network_name):\n        return list(args), {}\n\n    rewritten = list(args)\n    requested_map: dict[int, int] = {}\n    i = sub_idx + 1\n    while i < len(rewritten):\n        tok = rewritten[i]\n        if tok in ("-p", "--publish") and i + 1 < len(rewritten):\n            parsed = parse_publish_spec(rewritten[i + 1])\n            if parsed is not None:\n                _, hport, cport, _ = parsed\n                rewritten[i + 1] = f"127.0.0.1::{cport}"\n                requested_map[cport] = hport\n            i += 2\n            continue\n        if tok.startswith("-p=") or tok.startswith("--publish="):\n            prefix, val = tok.split("=", 1)\n            parsed = parse_publish_spec(val)\n            if parsed is not None:\n                _, hport, cport, _ = parsed\n                rewritten[i] = f"{prefix}=127.0.0.1::{cport}"\n                requested_map[cport] = hport\n        i += 1\n    return rewritten, requested_map\n\n\nclass StateStore:\n    def __init__(self, state_dir: Path | None = None) -> None:\n        self.state_dir = state_dir or STATE_DIR\n        self.lock_path = self.state_dir / "state.lock"\n        self.state_path = self.state_dir / "state.json"\n\n    def __enter__(self) -> dict[str, Any]:\n        self.state_dir.mkdir(parents=True, exist_ok=True)\n        self._lock_file = open(self.lock_path, "a+", encoding="utf-8")\n        fcntl.flock(self._lock_file.fileno(), fcntl.LOCK_EX)\n        self._data = self._read()\n        return self._data\n\n    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:\n        try:\n            if exc_type is None:\n                self._write(self._data)\n        finally:\n            try:\n                fcntl.flock(self._lock_file.fileno(), fcntl.LOCK_UN)\n            finally:\n                self._lock_file.close()\n\n    def _read(self) -> dict[str, Any]:\n        try:\n            raw = self.state_path.read_text(encoding="utf-8")\n            data = json.loads(raw)\n            if isinstance(data, dict):\n                data.setdefault("runner_id", None)\n                data.setdefault("networks", {})\n                data.setdefault("containers", {})\n                return data\n        except FileNotFoundError:\n            pass\n        except (OSError, ValueError) as exc:\n            sys.stderr.write(f"[docker-wrapper] warning: resetting corrupt state {self.state_path}: {exc}\\n")\n        return {"runner_id": None, "networks": {}, "containers": {}}\n\n    def _write(self, data: dict[str, Any]) -> None:\n        fd, tmp_path = tempfile.mkstemp(dir=str(self.state_dir), prefix="state.", suffix=".tmp")\n        try:\n            with os.fdopen(fd, "w", encoding="utf-8") as handle:\n                json.dump(data, handle, indent=2, sort_keys=True)\n                handle.flush()\n                os.fsync(handle.fileno())\n            os.replace(tmp_path, self.state_path)\n        except BaseException:\n            try:\n                os.unlink(tmp_path)\n            except OSError:\n                pass\n            raise\n\n\ndef run_docker(global_args: list[str], sub_args: list[str], *, check: bool = True) -> subprocess.CompletedProcess[str]:\n    cmd = [REAL_DOCKER, *global_args, *sub_args]\n    res = subprocess.run(cmd, text=True, capture_output=True)\n    if check and res.returncode != 0:\n        detail = (res.stderr or res.stdout or "").strip()\n        joined = " ".join(sub_args)\n        raise RuntimeError(f"docker {joined} failed (rc={res.returncode}): {detail}")\n    return res\n\n\ndef detect_self_container_id(global_args: list[str]) -> str | None:\n    override = os.environ.get("GHA_RUNNER_CONTAINER_ID")\n    if override:\n        return override.strip()\n    candidates: list[str] = []\n    hostname = os.environ.get("HOSTNAME") or socket.gethostname()\n    if hostname:\n        candidates.append(hostname.strip())\n    runner_name = os.environ.get("RUNNER_NAME")\n    if runner_name and runner_name not in candidates:\n        candidates.append(runner_name.strip())\n    for cand in candidates:\n        res = run_docker(global_args, ["inspect", "--format", "{{.Id}}", cand], check=False)\n        if res.returncode == 0 and res.stdout.strip():\n            return res.stdout.strip().splitlines()[0].strip()\n    return None\n\n\ndef verify_pid_is_owned_socat(pid: int, local_port: int, target_ip: str, target_port: int) -> bool:\n    if pid <= 1:\n        return False\n    proc_cmdline = Path(f"/proc/{pid}/cmdline")\n    if proc_cmdline.exists():\n        try:\n            raw = proc_cmdline.read_bytes()\n            if not raw:\n                return False\n            parts = [p.decode("utf-8", errors="replace") for p in raw.split(b"\\x00") if p]\n            cmdline_str = " ".join(parts)\n            return (\n                bool(parts)\n                and ("socat" in Path(parts[0]).name)\n                and f"TCP-LISTEN:{local_port}," in cmdline_str\n                and f"TCP:{target_ip}:{target_port}" in cmdline_str\n            )\n        except OSError:\n            return False\n    try:\n        out = subprocess.check_output(\n            ["ps", "-p", str(pid), "-o", "command="],\n            text=True,\n            stderr=subprocess.DEVNULL,\n        ).strip()\n        return (\n            "socat" in out\n            and f"TCP-LISTEN:{local_port}," in out\n            and f"TCP:{target_ip}:{target_port}" in out\n        )\n    except (OSError, subprocess.SubprocessError):\n        return False\n\n\ndef terminate_owned_relay(relay: dict[str, Any]) -> None:\n    pid = int(relay.get("pid") or 0)\n    local_port = int(relay.get("local_port") or 0)\n    target_ip = str(relay.get("target_ip") or "")\n    target_port = int(relay.get("target_port") or 0)\n    if pid <= 1 or not verify_pid_is_owned_socat(pid, local_port, target_ip, target_port):\n        return\n    try:\n        os.kill(pid, signal.SIGTERM)\n    except ProcessLookupError:\n        return\n    except PermissionError as exc:\n        sys.stderr.write(f"[docker-wrapper] warning: could not SIGTERM relay pid={pid}: {exc}\\n")\n        return\n    deadline = time.monotonic() + 1.0\n    while time.monotonic() < deadline:\n        if not verify_pid_is_owned_socat(pid, local_port, target_ip, target_port):\n            return\n        time.sleep(0.02)\n    if verify_pid_is_owned_socat(pid, local_port, target_ip, target_port):\n        try:\n            os.kill(pid, signal.SIGKILL)\n        except OSError:\n            pass\n\n\ndef start_owned_relay(local_port: int, target_ip: str, target_port: int) -> int:\n    proc = subprocess.Popen(\n        [\n            "socat",\n            f"TCP-LISTEN:{local_port},bind=127.0.0.1,reuseaddr,fork",\n            f"TCP:{target_ip}:{target_port}",\n        ],\n        stdin=subprocess.DEVNULL,\n        stdout=subprocess.DEVNULL,\n        stderr=subprocess.PIPE,\n        text=True,\n        start_new_session=True,\n    )\n    time.sleep(0.05)\n    if proc.poll() is not None:\n        err = (proc.stderr.read() if proc.stderr else "").strip()\n        raise RuntimeError(\n            f"socat relay for 127.0.0.1:{local_port} -> {target_ip}:{target_port} exited immediately "\n            f"(rc={proc.returncode}): {err}"\n        )\n    if proc.stderr is not None:\n        proc.stderr.close()\n    return proc.pid\n\n\ndef wait_for_tcp_handshake(host: str, port: int, timeout_sec: float = HANDSHAKE_TIMEOUT_SEC) -> None:\n    if timeout_sec <= 0:\n        return\n    deadline = time.monotonic() + timeout_sec\n    last_err: Exception | None = None\n    while True:\n        remaining = deadline - time.monotonic()\n        if remaining <= 0:\n            raise RuntimeError(\n                f"Timed out after {timeout_sec:.1f}s waiting for TCP reachability to {host}:{port} "\n                f"(last_error={last_err})"\n            )\n        attempt_timeout = min(1.0, max(0.05, remaining))\n        try:\n            with socket.create_connection((host, port), timeout=attempt_timeout):\n                return\n        except OSError as exc:\n            last_err = exc\n            time.sleep(min(0.1, max(0.01, deadline - time.monotonic())))\n\n\ndef ensure_runner_attached_to_network(\n    global_args: list[str],\n    state: dict[str, Any],\n    network_name: str,\n) -> str:\n    runner_id = state.get("runner_id") or detect_self_container_id(global_args)\n    if not runner_id:\n        raise RuntimeError("Could not determine self runner container ID for network attachment")\n    state["runner_id"] = runner_id\n\n    inspect_res = run_docker(global_args, ["inspect", runner_id], check=True)\n    runner_info = json.loads(inspect_res.stdout)[0]\n    attached_nets = (runner_info.get("NetworkSettings") or {}).get("Networks") or {}\n    if "bridge" not in attached_nets:\n        raise RuntimeError(f"Runner container {runner_id[:12]} is not attached to default \'bridge\' network")\n\n    net_entry = state["networks"].get(network_name)\n    if network_name not in attached_nets:\n        conn_res = run_docker(\n            global_args,\n            ["network", "connect", "--gw-priority", "-1", network_name, runner_id],\n            check=False,\n        )\n        if conn_res.returncode != 0:\n            recheck = run_docker(global_args, ["inspect", runner_id], check=True)\n            recheck_nets = (json.loads(recheck.stdout)[0].get("NetworkSettings") or {}).get("Networks") or {}\n            if network_name not in recheck_nets:\n                detail = (conn_res.stderr or conn_res.stdout or "").strip()\n                raise RuntimeError(\n                    f"Failed to attach runner {runner_id[:12]} to job network {network_name}: {detail}"\n                )\n        post_res = run_docker(global_args, ["inspect", runner_id], check=True)\n        post_nets = (json.loads(post_res.stdout)[0].get("NetworkSettings") or {}).get("Networks") or {}\n        if "bridge" not in post_nets or not (post_nets["bridge"].get("Gateway") or ""):\n            raise RuntimeError(\n                f"Runner {runner_id[:12]} default bridge gateway was lost after attaching {network_name}"\n            )\n        if net_entry is None:\n            net_id_res = run_docker(\n                global_args,\n                ["network", "inspect", "--format", "{{.Id}}", network_name],\n                check=False,\n            )\n            net_id = net_id_res.stdout.strip() if net_id_res.returncode == 0 else network_name\n            state["networks"][network_name] = {\n                "network_id": net_id,\n                "runner_id": runner_id,\n                "owned_by_wrapper": True,\n                "containers": [],\n            }\n    else:\n        if net_entry is None:\n            net_id_res = run_docker(\n                global_args,\n                ["network", "inspect", "--format", "{{.Id}}", network_name],\n                check=False,\n            )\n            net_id = net_id_res.stdout.strip() if net_id_res.returncode == 0 else network_name\n            state["networks"][network_name] = {\n                "network_id": net_id,\n                "runner_id": runner_id,\n                "owned_by_wrapper": False,\n                "containers": [],\n            }\n    return runner_id\n\n\ndef detach_runner_from_network_if_unused(\n    global_args: list[str],\n    state: dict[str, Any],\n    network_name: str,\n    *,\n    force: bool = False,\n) -> None:\n    net_entry = state["networks"].get(network_name)\n    if not net_entry:\n        return\n    active_cids = [cid for cid in net_entry.get("containers", []) if cid in state["containers"]]\n    net_entry["containers"] = active_cids\n    if active_cids and not force:\n        return\n    if net_entry.get("owned_by_wrapper"):\n        runner_id = net_entry.get("runner_id") or state.get("runner_id") or detect_self_container_id(global_args)\n        if runner_id:\n            disc = run_docker(global_args, ["network", "disconnect", network_name, runner_id], check=False)\n            if disc.returncode != 0:\n                err_txt = (disc.stderr or disc.stdout or "").lower()\n                if (\n                    "is not connected" not in err_txt\n                    and "not found" not in err_txt\n                    and "no such network" not in err_txt\n                ):\n                    run_docker(global_args, ["network", "disconnect", "-f", network_name, runner_id], check=False)\n    state["networks"].pop(network_name, None)\n\n\ndef cleanup_container_state(\n    global_args: list[str],\n    state: dict[str, Any],\n    cid_or_name: str,\n) -> None:\n    matched_cids: list[str] = []\n    for cid, cinfo in list(state["containers"].items()):\n        if cid == cid_or_name or cid.startswith(cid_or_name) or cinfo.get("name") == cid_or_name:\n            matched_cids.append(cid)\n    if not matched_cids:\n        res = run_docker(global_args, ["inspect", "--format", "{{.Id}}", cid_or_name], check=False)\n        if res.returncode == 0 and res.stdout.strip():\n            full_id = res.stdout.strip().splitlines()[0].strip()\n            if full_id in state["containers"]:\n                matched_cids.append(full_id)\n\n    for cid in matched_cids:\n        cinfo = state["containers"].pop(cid, {})\n        for relay in cinfo.get("relays", []):\n            terminate_owned_relay(relay)\n        for net_name in cinfo.get("networks", []):\n            if net_name in state["networks"]:\n                c_list = state["networks"][net_name].get("containers", [])\n                if cid in c_list:\n                    c_list.remove(cid)\n                detach_runner_from_network_if_unused(global_args, state, net_name)\n\n\ndef setup_service_container(\n    global_args: list[str],\n    state: dict[str, Any],\n    cid_or_name: str,\n    requested_ports_override: dict[int, int] | None = None,\n) -> None:\n    inspect_res = run_docker(global_args, ["inspect", cid_or_name], check=True)\n    info = json.loads(inspect_res.stdout)[0]\n    cid = str(info["Id"])\n    cname = str(info.get("Name") or "").lstrip("/")\n    net_settings = info.get("NetworkSettings") or {}\n    networks = net_settings.get("Networks") or {}\n\n    job_networks = [n for n in networks if NETWORK_NAME_RE.match(n)]\n    if not job_networks:\n        return\n\n    existing_entry = state["containers"].get(cid, {})\n    requested_ports: dict[str, int] = dict(existing_entry.get("requested_ports") or {})\n    if requested_ports_override:\n        for cport, hport in requested_ports_override.items():\n            requested_ports[str(cport)] = int(hport)\n\n    for old_relay in existing_entry.get("relays", []):\n        terminate_owned_relay(old_relay)\n\n    attached_job_networks: list[str] = []\n    target_ip = ""\n    try:\n        for net_name in job_networks:\n            ensure_runner_attached_to_network(global_args, state, net_name)\n            attached_job_networks.append(net_name)\n            net_entry = state["networks"][net_name]\n            if cid not in net_entry["containers"]:\n                net_entry["containers"].append(cid)\n            ip_candidate = (networks.get(net_name) or {}).get("IPAddress") or ""\n            if ip_candidate and not target_ip:\n                target_ip = ip_candidate\n\n        if not target_ip:\n            raise RuntimeError(f"Service container {cid[:12]} on {job_networks} has no IPv4 address")\n\n        ports = net_settings.get("Ports") or {}\n        new_relays: list[dict[str, Any]] = []\n        for cport_proto, bindings in ports.items():\n            if not cport_proto.endswith("/tcp") or not bindings:\n                continue\n            cport = int(cport_proto.split("/", 1)[0])\n            local_ports: set[int] = set()\n            for binding in bindings:\n                hport = int(binding.get("HostPort") or 0)\n                if hport > 0:\n                    local_ports.add(hport)\n            req_hport = requested_ports.get(str(cport))\n            if req_hport:\n                local_ports.add(int(req_hport))\n            elif cport == 3306:\n                local_ports.add(3306)\n\n            if not local_ports:\n                continue\n\n            wait_for_tcp_handshake(target_ip, cport, timeout_sec=HANDSHAKE_TIMEOUT_SEC)\n            for lport in sorted(local_ports):\n                for other_cid, other_info in list(state["containers"].items()):\n                    if other_cid == cid:\n                        continue\n                    kept_relays = []\n                    for r in other_info.get("relays", []):\n                        if int(r.get("local_port") or 0) == lport:\n                            terminate_owned_relay(r)\n                        else:\n                            kept_relays.append(r)\n                    other_info["relays"] = kept_relays\n\n                pid = start_owned_relay(lport, target_ip, cport)\n                new_relays.append(\n                    {\n                        "pid": pid,\n                        "local_port": lport,\n                        "target_ip": target_ip,\n                        "target_port": cport,\n                    }\n                )\n                wait_for_tcp_handshake("127.0.0.1", lport, timeout_sec=5.0)\n    except BaseException:\n        for relay in locals().get("new_relays", []):\n            terminate_owned_relay(relay)\n        state["containers"].pop(cid, None)\n        for net_name in attached_job_networks:\n            if net_name in state["networks"] and cid in state["networks"][net_name].get("containers", []):\n                state["networks"][net_name]["containers"].remove(cid)\n            detach_runner_from_network_if_unused(global_args, state, net_name, force=True)\n        raise\n\n    state["containers"][cid] = {\n        "name": cname,\n        "networks": attached_job_networks,\n        "target_ip": target_ip,\n        "requested_ports": requested_ports,\n        "relays": new_relays,\n    }\n\n\ndef record_created_container(\n    global_args: list[str],\n    state: dict[str, Any],\n    cid: str,\n    sub_args: list[str],\n    requested_map: dict[int, int],\n) -> None:\n    if not requested_map:\n        return\n    cname = extract_option_value(sub_args, ("--name",)) or ""\n    net_name = extract_option_value(sub_args, ("--network", "--net")) or ""\n    state["containers"][cid] = {\n        "name": cname.lstrip("/"),\n        "networks": [net_name] if NETWORK_NAME_RE.match(net_name) else [],\n        "target_ip": "",\n        "requested_ports": {str(k): int(v) for k, v in requested_map.items()},\n        "relays": [],\n    }\n\n\ndef handle_port_command(global_args: list[str], sub_args: list[str]) -> int:\n    proc = run_docker(global_args, ["port", *sub_args], check=False)\n    sys.stderr.write(proc.stderr)\n    if proc.returncode != 0 or not sub_args:\n        sys.stdout.write(proc.stdout)\n        return proc.returncode\n\n    target_ref = sub_args[0]\n    requested_ports: dict[str, int] = {}\n    with StateStore() as state:\n        for cid, cinfo in state["containers"].items():\n            if cid == target_ref or cid.startswith(target_ref) or cinfo.get("name") == target_ref:\n                requested_ports = dict(cinfo.get("requested_ports") or {})\n                break\n\n    lines: list[str] = []\n    for line in proc.stdout.splitlines():\n        if " -> " in line:\n            cport_proto, _ = line.split(" -> ", 1)\n            if cport_proto.endswith("/tcp"):\n                cport_str = cport_proto.split("/", 1)[0]\n                if cport_str in requested_ports:\n                    lines.append(f"{cport_proto} -> 0.0.0.0:{requested_ports[cport_str]}")\n                    continue\n                if cport_str == "3306":\n                    lines.append("3306/tcp -> 0.0.0.0:3306")\n                    continue\n        lines.append(line)\n    if lines:\n        sys.stdout.write("\\n".join(lines) + "\\n")\n    return proc.returncode\n\n\ndef extract_positional_targets(sub_args: list[str], flags_with_value: frozenset[str] = frozenset()) -> list[str]:\n    targets: list[str] = []\n    i = 0\n    while i < len(sub_args):\n        tok = sub_args[i]\n        if tok == "--":\n            targets.extend(sub_args[i + 1 :])\n            break\n        if tok in flags_with_value:\n            i += 2\n            continue\n        if tok.startswith("-"):\n            i += 1\n            continue\n        targets.append(tok)\n        i += 1\n    return targets\n\n\ndef main(argv: list[str] | None = None) -> int:\n    raw_args = list(sys.argv[1:] if argv is None else argv)\n    rewritten_args, requested_map = rewrite_publish_args(raw_args)\n    global_args, subcmd, sub_args = split_global_and_sub_args(rewritten_args)\n\n    if subcmd == "port":\n        return handle_port_command(global_args, sub_args)\n\n    if subcmd == "create":\n        proc = run_docker(global_args, ["create", *sub_args], check=False)\n        if proc.returncode == 0 and requested_map and proc.stdout.strip():\n            cid = proc.stdout.strip().splitlines()[-1].strip()\n            with StateStore() as state:\n                record_created_container(global_args, state, cid, sub_args, requested_map)\n        sys.stdout.write(proc.stdout)\n        sys.stderr.write(proc.stderr)\n        return proc.returncode\n\n    if subcmd == "start" or (subcmd == "run" and any(a in ("-d", "--detach") for a in sub_args)):\n        proc = run_docker(global_args, [subcmd, *sub_args], check=False)\n        if proc.returncode != 0:\n            sys.stdout.write(proc.stdout)\n            sys.stderr.write(proc.stderr)\n            return proc.returncode\n\n        targets: list[str] = []\n        if subcmd == "run":\n            out_lines = [line.strip() for line in proc.stdout.splitlines() if line.strip()]\n            if out_lines:\n                targets.append(out_lines[-1])\n        else:\n            targets.extend(extract_positional_targets(sub_args, frozenset({"--detach-keys"})))\n\n        try:\n            with StateStore() as state:\n                for target in targets:\n                    setup_service_container(\n                        global_args,\n                        state,\n                        target,\n                        requested_ports_override=requested_map if subcmd == "run" else None,\n                    )\n        except Exception as exc:\n            sys.stderr.write(f"[docker-wrapper] error setting up service container reachability: {exc}\\n")\n            return 1\n\n        sys.stdout.write(proc.stdout)\n        sys.stderr.write(proc.stderr)\n        return proc.returncode\n\n    if subcmd in ("stop", "rm", "kill"):\n        value_flags = frozenset({"-t", "--time", "-s", "--signal"})\n        targets = extract_positional_targets(sub_args, value_flags)\n        with StateStore() as state:\n            for target in targets:\n                cleanup_container_state(global_args, state, target)\n        proc = run_docker(global_args, [subcmd, *sub_args], check=False)\n        sys.stdout.write(proc.stdout)\n        sys.stderr.write(proc.stderr)\n        return proc.returncode\n\n    if subcmd == "network" and sub_args:\n        net_action = sub_args[0]\n        net_rest = sub_args[1:]\n        if net_action == "rm":\n            targets = extract_positional_targets(net_rest)\n            with StateStore() as state:\n                for net_target in targets:\n                    for net_name, net_entry in list(state["networks"].items()):\n                        if net_name == net_target or net_entry.get("network_id", "").startswith(net_target):\n                            for cid in list(net_entry.get("containers", [])):\n                                cleanup_container_state(global_args, state, cid)\n                            detach_runner_from_network_if_unused(global_args, state, net_name, force=True)\n            proc = run_docker(global_args, ["network", *sub_args], check=False)\n            sys.stdout.write(proc.stdout)\n            sys.stderr.write(proc.stderr)\n            return proc.returncode\n\n    os.execv(REAL_DOCKER, [REAL_DOCKER, *rewritten_args])\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
JOB_COMPLETED = '#!/usr/bin/env bash\nset -Eeuo pipefail\nif [[ "${GHA_ADMISSION_REQUIRED:-0}" == 1 ]]; then\n  python3 - <<\'RELEASE_CLIENT\'\nimport runpy\nimport sys\nimport time\n\napi = runpy.run_path(\'/usr/local/bin/gha-host-admission.py\', run_name=\'gha_release_client\')\nrequest = api[\'request\']\nOrphanRunnerHook = api.get(\'OrphanRunnerHook\', ())\nfailures = 0\nwhile True:\n    try:\n        if request(\'release\') is True:\n            break\n    except OrphanRunnerHook:\n        # The Worker has ended. Its worker-bound row is reclaimed by the\n        # daemon; a stale completion hook must not clean a subsequent job.\n        print(\'Runner Worker ended; skipping stale completion cleanup\', file=sys.stderr)\n        raise SystemExit(75)\n    except RuntimeError as error:\n        # Existing containers still have the old request decoder. The root\n        # daemon also marks its terminal error in their error string.\n        if str(error).startswith(\'ORPHAN_RUNNER_HOOK: \'):\n            print(\'Runner Worker ended; skipping stale completion cleanup\', file=sys.stderr)\n            raise SystemExit(75)\n    except (OSError, ValueError, KeyError, TypeError):\n        # The daemon may restart or disconnect after removing the row but\n        # before replying. Release is idempotent for this Worker identity.\n        pass\n    failures += 1\n    if failures == 1 or failures % 12 == 0:\n        print(\'Runner lease release unacknowledged; retrying in 5 seconds\', file=sys.stderr)\n    # Each request retains its 30-second socket timeout. Do not abandon a\n    # Worker\'s release obligation or reuse it before the ACK.\n    time.sleep(5)\nRELEASE_CLIENT\nfi\nexec python3 /usr/local/bin/gha-runner-clean-target.py\n'
RUNNER_DOCKERFILE = 'FROM ghcr.io/actions/actions-runner:2.337.0\nARG DEBIAN_FRONTEND=noninteractive\nUSER root\nRUN apt-get update && DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends \\\n      build-essential clang cmake curl git jq libssl-dev make pkg-config python3 python3-pip \\\n      perl cpanminus libarchive-zip-perl zlib1g-dev libzstd-dev libarchive-dev ca-certificates unzip zip xz-utils \\\n      zstd socat iproute2 procps \\\n    && rm -rf /var/lib/apt/lists/* \\\n    && install -d -o runner -g runner /runner-state /work /opt/runner-rust/cargo /opt/runner-rust/rustup \\\n    && install -m 0444 /dev/null /run/oxidex-spot-runner\nCOPY entrypoint.sh /usr/local/bin/gha-runner-entrypoint\nCOPY job-completed.sh /usr/local/bin/gha-runner-job-completed.sh\nCOPY job-started.sh /usr/local/bin/gha-runner-job-started.sh\nCOPY host_admission.py /usr/local/bin/gha-host-admission.py\nCOPY clean_target.py /usr/local/bin/gha-runner-clean-target.py\nCOPY docker-wrapper.py /usr/local/bin/docker\nRUN chmod 0755 /usr/local/bin/docker /usr/local/bin/gha-runner-job-started.sh /usr/local/bin/gha-runner-entrypoint /usr/local/bin/gha-runner-job-completed.sh\nUSER runner\nENV CARGO_HOME=/opt/runner-rust/cargo\nENV RUSTUP_HOME=/opt/runner-rust/rustup\nENV PATH=/opt/runner-rust/cargo/bin:${PATH}\nRUN curl --proto \'=https\' --tlsv1.2 -fsS https://sh.rustup.rs -o /tmp/rustup-init.sh \\\n    && sh /tmp/rustup-init.sh -y --profile minimal --default-toolchain 1.99.0 \\\n    && rm /tmp/rustup-init.sh \\\n    && rustup component add rustfmt clippy --toolchain 1.99.0 \\\n    && rustup target add --toolchain 1.99.0 x86_64-unknown-linux-musl aarch64-unknown-linux-musl aarch64-apple-darwin x86_64-apple-darwin \\\n    && rustc --version | grep \'^rustc 1.99.0 \' \\\n    && cargo --version | grep \'^cargo 1.99.0 \'\nUSER root\nRUN chown -R root:root /opt/runner-rust \\\n    && chmod -R a-w /opt/runner-rust\nUSER runner\nENV CARGO_HOME=/work/.cargo\nENV PATH=/opt/runner-rust/cargo/bin:/work/.cargo/bin:${PATH}\nRUN test ! -w /opt/runner-rust/cargo/bin/rustup \\\n    && test ! -w /opt/runner-rust/rustup\nWORKDIR /work\nENV RUNNER_STATE=/runner-state\nENV OXIDEX_CLEAN_TARGET=1\nENV ACTIONS_RUNNER_HOOK_JOB_STARTED=/usr/local/bin/gha-runner-job-started.sh\nENV ACTIONS_RUNNER_HOOK_JOB_COMPLETED=/usr/local/bin/gha-runner-job-completed.sh\nENTRYPOINT ["/usr/local/bin/gha-runner-entrypoint"]\n'
RUNNER_ENTRYPOINT = '#!/usr/bin/env bash\nset -Eeuo pipefail\n\nstate="${RUNNER_STATE:-/runner-state}"\nconfig="$state/.runner"\nmkdir -p "$state"\nif [[ ! -x "$state/run.sh" ]]; then\n  cp -a /home/runner/. "$state/"\nfi\ncd "$state"\nif [[ "${RUNNER_CONFIGURE_ONLY:-0}" == 1 ]]; then\n  if [[ -f "$config" ]]; then\n    exit 0\n  fi\n  : "${GITHUB_RUNNER_URL:?GITHUB_RUNNER_URL is required}"\n  : "${GITHUB_RUNNER_TOKEN:?GITHUB_RUNNER_TOKEN is required for initial registration}"\n  ./config.sh --unattended --replace --url "$GITHUB_RUNNER_URL" \\\n    --token "$GITHUB_RUNNER_TOKEN" --name "$RUNNER_NAME" \\\n    --labels "$RUNNER_LABELS" --runnergroup "$RUNNER_GROUP_NAME" \\\n    --work /work\n  exit 0\nfi\nif [[ ! -f "$config" ]]; then\n  echo "Runner state is not registered at $config" >&2\n  exit 1\nfi\nexec ./run.sh\n'
STARTUP_SCRIPT = '#!/usr/bin/env bash\n# Rendered by spot_runner_manager.py and delivered as GCE startup-script metadata.\nset -Eeuo pipefail\nset +x\nexec > >(tee -a /var/log/gha-runner-bootstrap.log) 2>&1\n\nexport DEBIAN_FRONTEND=noninteractive\nDEVICE="{{DISK_DEVICE}}"\nMOUNT_POINT=/mnt/runner-data\nif [[ ! -b "$DEVICE" ]]; then echo "Missing persistent runner disk $DEVICE" >&2; exit 1; fi\nif ! blkid "$DEVICE" >/dev/null 2>&1; then mkfs.ext4 -F "$DEVICE"; fi\nmkdir -p "$MOUNT_POINT"\nUUID=$(blkid -s UUID -o value "$DEVICE")\ngrep -q "$UUID" /etc/fstab || echo "UUID=$UUID $MOUNT_POINT ext4 defaults,nofail 0 2" >>/etc/fstab\nmountpoint -q "$MOUNT_POINT" || mount "$MOUNT_POINT"\nmkdir -p "$MOUNT_POINT/apt/lists/partial" "$MOUNT_POINT/apt/cache/archives/partial"\ncat >/etc/apt/apt.conf.d/99runner-data <<EOF\nDir::State::lists "$MOUNT_POINT/apt/lists";\nDir::Cache "$MOUNT_POINT/apt/cache";\nEOF\n\nrequired_packages=(ca-certificates curl gnupg git jq xfsprogs util-linux rsync)\nmissing_packages=()\nfor package in "${required_packages[@]}"; do\n  dpkg-query -W -f=\'${Status}\' "$package" 2>/dev/null | grep -q \'install ok installed\' || missing_packages+=("$package")\ndone\nif ((${#missing_packages[@]})); then\n  apt-get clean\n  rm -rf /var/lib/apt/lists/*\n  apt-get update\n  apt-get install -y "${missing_packages[@]}"\nfi\ninstall -m 0755 -d /etc/apt/keyrings\ncurl -fsSL https://download.docker.com/linux/debian/gpg -o /etc/apt/keyrings/docker.asc\nchmod a+r /etc/apt/keyrings/docker.asc\necho "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/debian $(. /etc/os-release && echo "$VERSION_CODENAME") stable" >/etc/apt/sources.list.d/docker.list\napt-get clean\nrm -rf /var/lib/apt/lists/*\napt-get update\napt-get install -y docker-ce docker-ce-cli containerd.io docker-buildx-plugin docker-compose-plugin\nmkdir -p "$MOUNT_POINT/docker" "$MOUNT_POINT/instances" "$MOUNT_POINT/work"\nmkdir -p "$MOUNT_POINT/containerd"\ncat >/etc/docker/daemon.json <<EOF\n{"data-root":"$MOUNT_POINT/docker","log-driver":"local","log-opts":{"max-size":"20m","max-file":"3"}}\nEOF\n# Docker\'s data-root alone does not move containerd snapshots. Copy its current\n# content once, then point containerd at the persistent data disk before Docker\n# starts. This puts image overlays (what `df /` inside a job sees) on the 100 GB\n# disk too, rather than filling the VM\'s small boot disk.\nsystemctl stop docker || true\nsystemctl stop containerd || true\ncontainerd_exec=$(systemctl show -p ExecStart --value containerd)\nif [[ "$containerd_exec" != *"--root $MOUNT_POINT/containerd"* ]]; then\n  # Repeat an interrupted copy safely from the untouched boot-disk source.\n  cp -a /var/lib/containerd/. "$MOUNT_POINT/containerd/"\nfi\ninstall -d -m 0755 /etc/systemd/system/containerd.service.d\ncat >/etc/systemd/system/containerd.service.d/runner-data.conf <<EOF\n[Service]\nExecStart=\nExecStart=/usr/bin/containerd --root $MOUNT_POINT/containerd --state /run/containerd\nEOF\nsystemctl daemon-reload\nsystemctl enable --now containerd\nsystemctl enable docker\nsystemctl restart docker\ncontainerd_exec=$(systemctl show -p ExecStart --value containerd)\n[[ "$containerd_exec" == *"--root $MOUNT_POINT/containerd"* ]] || { echo "containerd service root is unexpected: $containerd_exec" >&2; exit 1; }\ndocker_root=$(docker info --format=json | jq -r .DockerRootDir)\n[[ "$docker_root" == "$MOUNT_POINT/docker" ]] || { echo "Docker root is $docker_root, expected $MOUNT_POINT/docker" >&2; exit 1; }\n# Remove the previous default roots after both services use the persistent disk.\nrm -rf /var/lib/containerd/* /var/lib/docker/* /var/lib/apt/lists/* /var/cache/apt/archives/*\napt-get clean\n\ninstall -d -m 0755 /opt/gha-runners/build\nRESOURCE_MONITORING={{RESOURCE_MONITORING}}\nif [[ "$RESOURCE_MONITORING" == 1 ]]; then\n  curl --proto \'=https\' --tlsv1.2 -fsS https://dl.google.com/cloudagents/add-google-cloud-ops-agent-repo.sh -o /run/install-ops-agent.sh\n  bash /run/install-ops-agent.sh --also-install\n  rm /run/install-ops-agent.sh\n  cat >/etc/google-cloud-ops-agent/config.yaml <<\'METRICS\'\nlogging:\n  service:\n    pipelines:\n      default_pipeline:\n        receivers: []\nmetrics:\n  receivers:\n    hostmetrics:\n      type: hostmetrics\n      collection_interval: 60s\n  processors:\n    metrics_filter:\n      type: exclude_metrics\n      metrics_pattern:\n        - agent.googleapis.com/cpu/*\n        - agent.googleapis.com/disk/*\n        - agent.googleapis.com/interface/*\n        - agent.googleapis.com/network/*\n        - agent.googleapis.com/swap/*\n        - agent.googleapis.com/processes/*\n  service:\n    pipelines:\n      default_pipeline:\n        receivers: [hostmetrics]\n        processors: [metrics_filter]\nMETRICS\n  systemctl restart google-cloud-ops-agent\nfi\nprintf \'%s\' \'{{DOCKERFILE_B64}}\' | base64 -d >/opt/gha-runners/build/Dockerfile\nprintf \'%s\' \'{{ENTRYPOINT_B64}}\' | base64 -d >/opt/gha-runners/build/entrypoint.sh\nprintf \'%s\' \'{{JOB_COMPLETED_B64}}\' | base64 -d >/opt/gha-runners/build/job-completed.sh\nprintf \'%s\' \'{{CLEAN_TARGET_B64}}\' | base64 -d >/opt/gha-runners/build/clean_target.py\nprintf \'%s\' \'{{DOCKER_WRAPPER_B64}}\' | base64 -d >/opt/gha-runners/build/docker-wrapper.py\nchmod 0755 /opt/gha-runners/build/docker-wrapper.py\nprintf \'%s\' \'{{ADMISSION_B64}}\' | base64 -d >/opt/gha-runners/build/host_admission.py\nprintf \'%s\' \'{{JOB_STARTED_B64}}\' | base64 -d >/opt/gha-runners/build/job-started.sh\nprintf \'%s\' \'{{EVIDENCE_B64}}\' | base64 -d >/opt/gha-runners/host_evidence.py\nTIERED={{TIERED}}\nSTRICT_HEAVY_POOL={{STRICT_HEAVY_POOL}}\nif [[ "$TIERED" == 1 ]]; then\n  install -d -m 0755 /run/gha-admission\n  cp /opt/gha-runners/build/host_admission.py /opt/gha-runners/host_admission.py\n  printf \'%s\' \'{{DOCKER_ADMISSION_B64}}\' | base64 -d >/usr/local/bin/docker\n  chmod 0755 /usr/local/bin/docker\n  python3 - <<\'ADMISSION_CONFIG\'\nimport json, socket\nnames = [\'{{RUNNER_PREFIX}}-\'+socket.gethostname().split(\'.\')[0]+\'-\'+str(i) for i in range(1,{{RUNNER_COUNT}}+1)]\nconfig=dict(work_gib={{ADMISSION_WORK_GIB}},runner_gib={{RUNNER_MEMORY_GB}},builder_gib={{BUILDER_MEMORY_GIB}},runner_names=names)\nif {{STRICT_HEAVY_POOL}}:\n    config.update(role=\'runner\',heavy_runners=names)\nwith open(\'/etc/gha-admission.json\',\'w\') as target:\n    json.dump(config,target)\nADMISSION_CONFIG\n  chmod 0644 /etc/gha-admission.json\n  cat >/etc/systemd/system/gha-admission.service <<\'ADMISSION_SERVICE\'\n[Unit]\nDescription=Shared runner and builder memory admission\nAfter=docker.service\nRequires=docker.service\n[Service]\nExecStart=/usr/bin/python3 /opt/gha-runners/host_admission.py serve\nRestart=always\nRestartSec=5\n[Install]\nWantedBy=multi-user.target\nADMISSION_SERVICE\n  systemctl daemon-reload\n  systemctl enable --now gha-admission\n  for attempt in $(seq 1 30); do [[ ! -S /run/gha-admission/socket ]] || break; sleep 1; done\n  [[ -S /run/gha-admission/socket ]] || exit 1\nfi\nchmod 0755 /opt/gha-runners/build/entrypoint.sh\ndocker build --pull -t oxidex-self-hosted-runner:{{RUNNER_VERSION}} /opt/gha-runners/build\n\nREMOTE_BUILDER={{REMOTE_BUILDER}}\nif [[ "$REMOTE_BUILDER" == 1 ]]; then\n  install -d -m 0755 /opt/gha-runners/builder\n  printf \'%s\' \'{{BUILDER_DOCKERFILE_B64}}\' | base64 -d >/opt/gha-runners/builder/Dockerfile\n  printf \'%s\' \'{{BUILDER_ENTRYPOINT_B64}}\' | base64 -d >/opt/gha-runners/builder/entrypoint.py\n  printf \'%s\' \'{{HOST_LAUNCHER_B64}}\' | base64 -d >/usr/local/bin/oxidex-remote-build\n  chmod 0755 /usr/local/bin/oxidex-remote-build\n  printf \'%s\\n\' \'{"cpus":{{BUILDER_CPUS}},"memory_gib":{{BUILDER_MEMORY_GIB}}}\' >/etc/oxidex-remote-build.json\n  chmod 0644 /etc/oxidex-remote-build.json\n  docker build -t oxidex-remote-builder:1.97.1 /opt/gha-runners/builder\nfi\n\nORG_URL=https://github.com/{{ORG}}\nRUNNER_LABELS=\'{{RUNNER_LABELS}}\'\nRUNNER_GROUP=\'{{RUNNER_GROUP}}\'\nRUNNER_PREFIX=\'{{RUNNER_PREFIX}}\'\nRUNNER_IMAGE=$(docker image inspect oxidex-self-hosted-runner:{{RUNNER_VERSION}} | jq -er \'.[0].Id\')\n[[ "$RUNNER_IMAGE" =~ ^sha256:[0-9a-f]{64}$ ]] || exit 1\nRUST_VOLUME="gha-rust-${RUNNER_IMAGE#sha256:}"\nREGISTRATION_TOKEN={{REGISTRATION_TOKEN}}\nRUNNER_COUNT={{RUNNER_COUNT}}\nRUNNER_MEMORY_GB={{RUNNER_MEMORY_GB}}\n# Empty unless fixed sizing requested an explicit per-runner vCPU cap.\nRUNNER_CPU_LIMIT=\'{{RUNNER_CPU_LIMIT}}\'\n# Docker Engine storage (images, layers, build cache and containers) must stay\n# on the mounted persistent data disk. Stop if it did not mount as expected.\ndocker_root=$(docker info --format=json | jq -r .DockerRootDir)\n[[ "$docker_root" == "$MOUNT_POINT/docker" ]] || { echo "Docker root is $docker_root, expected $MOUNT_POINT/docker" >&2; exit 1; }\nfor i in $(seq 1 "$RUNNER_COUNT"); do\n  name="${RUNNER_PREFIX}-$(hostname -s)-${i}"\n  state="$MOUNT_POINT/instances/$name"\n  work="$MOUNT_POINT/work/$name"\n  mkdir -p "$state" "$work"\n  chown -R 1001:1001 "$state" "$work"\n  runner_labels="$RUNNER_LABELS"\n  env_file="/run/${name}.env"\n  umask 077\n  printf \'GITHUB_RUNNER_TOKEN=%s\\n\' "$REGISTRATION_TOKEN" >"$env_file"\n  docker run --rm --env-file "$env_file" -e RUNNER_CONFIGURE_ONLY=1 \\\n    -e RUNNER_NAME="$name" -e RUNNER_LABELS="$runner_labels" \\\n    -e RUNNER_GROUP_NAME="$RUNNER_GROUP" -e GITHUB_RUNNER_URL="$ORG_URL" \\\n    -e RUNNER_STATE=/runner-state \\\n    -v "$state:/runner-state" -v "$work:/work" "$RUNNER_IMAGE"\n  rm -f "$env_file"\n  docker rm -f "$name" >/dev/null 2>&1 || true\n  # Equal CPU weights split cores only under contention; an idle host lets one\n  # job use every vCPU. Memory stays capped so one job cannot starve the others.\n  docker_args=(-d --restart unless-stopped --cpu-shares=1024 --memory="${RUNNER_MEMORY_GB}g" \\\n    --name "$name" -e RUNNER_NAME="$name" -e RUNNER_LABELS="$runner_labels" \\\n    -e RUNNER_GROUP_NAME="$RUNNER_GROUP" -e GITHUB_RUNNER_URL="$ORG_URL" \\\n    -e RUNNER_STATE=/runner-state -v "$state:/runner-state" -v "$work:/work")\n  if [[ "$TIERED" == 1 ]]; then\n    docker_args+=(-e GHA_ADMISSION_REQUIRED=1 -v /run/gha-admission:/run/gha-admission:ro)\n  fi\n  [[ -z "$RUNNER_CPU_LIMIT" ]] || docker_args+=(--cpus="$RUNNER_CPU_LIMIT")\n  docker_args+=(--mount "type=volume,src=$RUST_VOLUME,dst=/opt/runner-rust,readonly")\n  [[ "$STRICT_HEAVY_POOL" != 1 ]] || docker_args+=(--memory-swap="32g")\n  docker_args+=("$RUNNER_IMAGE")\n  docker run "${docker_args[@]}"\ndone\nunset REGISTRATION_TOKEN\nprintf \'%s\\n\' \'{{DEPLOYMENT_ID}}\' >/var/lib/gha-runner-bootstrap.complete\n'
